// Source-driven adaptation of Dime Views/BudgetView.swift and NewBudgetView.swift.
import SwiftUI
import CoreData
struct DimeBudgetView: View {
 @EnvironmentObject private var coreDataModel: CoreDataModel
 @FetchRequest(sortDescriptors:[NSSortDescriptor(key:"createdAt",ascending:true)]) private var budgets: FetchedResults<DimeBudgetEntity>
 @StateObject private var adapter=DimeBudgetDataAdapter()
 @State private var showEditor=false
 @State private var selected:DimeBudgetEntity?
 var body: some View { NavigationStack { Group { if budgets.isEmpty { VStack(spacing:12){ Image(systemName:"chart.pie").font(.system(size:46,weight:.medium,design:.rounded)).foregroundColor(Color.SubtitleText); Text("Dime Budget Empty").font(.system(.title2,design:.rounded).weight(.medium)); Text("Dime Budget Empty Description").font(.system(.body,design:.rounded)).foregroundColor(Color.SubtitleText) }.frame(maxWidth:.infinity,maxHeight:.infinity) } else { ScrollView { LazyVStack(spacing:14) { ForEach(budgets) { budget in DimeBudgetCard(budget:budget,snapshot:adapter.snapshot(for:budget,spendings:coreDataModel.savedSpendings)).onTapGesture{selected=budget} } }.padding(20) } } }.background(Color.PrimaryBackground).navigationTitle("Dime Budget Title").toolbar { Button { showEditor=true } label:{Image(systemName:"plus")} } }.sheet(isPresented:$showEditor){DimeBudgetEditor().environmentObject(coreDataModel)}.sheet(item:$selected){DimeBudgetEditor(budget:$0).environmentObject(coreDataModel)} }
}
struct DimeBudgetCard: View { let budget:DimeBudgetEntity; let snapshot:DimeBudgetSnapshot; var body:some View { VStack(alignment:.leading,spacing:12){ HStack { Text(budget.category?.name ?? String(localized:"Dime Budget Overall")).font(.system(.title3,design:.rounded).weight(.semibold)); Spacer(); Text(snapshot.remaining,format:.currency(code:"EUR")).foregroundColor(snapshot.remaining < 0 ? Color.AlertRed : Color.IncomeGreen) }; ProgressView(value:snapshot.fraction).tint(snapshot.spent > snapshot.limit ? Color.AlertRed : Color.IncomeGreen); HStack { Text(snapshot.spent,format:.currency(code:"EUR")); Spacer(); Text(snapshot.limit,format:.currency(code:"EUR")) }.font(.system(.subheadline,design:.rounded)).foregroundColor(Color.SubtitleText) }.padding(16).background(Color.SecondaryBackground,in:RoundedRectangle(cornerRadius:18,style:.continuous)) } }
struct DimeBudgetEditor: View { @EnvironmentObject private var coreDataModel:CoreDataModel; @Environment(\.dismiss) private var dismiss; @FetchRequest(sortDescriptors:[NSSortDescriptor(key:"name",ascending:true)],predicate:NSPredicate(format:"isShadowed == false")) private var categories:FetchedResults<CategoryEntity>; let budget:DimeBudgetEntity?; @State private var amount:Double; @State private var category:CategoryEntity?; @State private var period:DimeBudgetPeriod; init(budget:DimeBudgetEntity?=nil){self.budget=budget;_amount=State(initialValue:budget?.amount ?? 0);_category=State(initialValue:budget?.category);_period=State(initialValue:DimeBudgetPeriod(rawValue:budget?.period ?? 2) ?? .month)}; var body:some View { NavigationStack { Form { TextField("Dime Budget Amount",value:$amount,format:.number); Picker("Dime Budget Period",selection:$period){ForEach(DimeBudgetPeriod.allCases){Text($0.title).tag($0)}}; Picker("Dime Budget Category",selection:$category){Text("Dime Budget Overall").tag(CategoryEntity?.none);ForEach(categories){Text($0.name ?? "").tag(Optional($0))}} }.navigationTitle("Dime Budget Edit").toolbar { ToolbarItem(placement:.cancellationAction){Button("Dime Budget Cancel"){dismiss()}};ToolbarItem(placement:.primaryAction){Button("Dime Budget Save"){let v=DimeBudgetLocal(amount:amount,categoryID:category?.id,period:period,startDate:.now);if let budget{coreDataModel.editDimeBudget(budget,with:v)}else{coreDataModel.addDimeBudget(v)};dismiss()}.disabled(amount <= 0)}} } }
extension DimeBudgetPeriod { var title:LocalizedStringKey { self == .week ? "Dime Budget Week" : self == .month ? "Dime Budget Month" : "Dime Budget Year" } }
